package com.aadil.jobtracker.UserController;import com.aadil.jobtracker.UserRepository.SortDirection;import com.aadil.jobtracker.UserRepository.UserSortField;import com.aadil.jobtracker.UserService.UserServiceImp;import com.aadil.jobtracker.Validation.UserRequestDTO;import com.aadil.jobtracker.Validation.UserResponseDTO;import com.aadil.jobtracker.responses.APIResponse;import com.aadil.jobtracker.responses.PagedResponse;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.util.List;import java.util.Optional;@RestController@RequestMapping("/users")@Validatedpublic class UserController {    private final UserServiceImp userServiceImp;    public UserController(UserServiceImp userServiceImp) {        this.userServiceImp = userServiceImp;    }    @PostMapping("/{id}")    public ResponseEntity<UserResponseDTO> createUser (@Valid @RequestBody UserRequestDTO dto){        UserResponseDTO responseDTO = userServiceImp.createUser(dto);        APIResponse<UserResponseDTO> apiResponse = new APIResponse<>();        apiResponse.setStatus(true);        apiResponse.setMessage("User Created Successfully");        apiResponse.setCode("USER_CREATED");        apiResponse.setData(responseDTO);        return ResponseEntity.ok(responseDTO);    }    @PostMapping ("/bulk")    public ResponseEntity<List<UserResponseDTO>> createUsers (@Valid @RequestBody List<UserRequestDTO> dtos){        List<UserResponseDTO> responseDTOS = userServiceImp.createUsers(dtos);       APIResponse<List<UserResponseDTO>> apiResponse = new APIResponse<>();       apiResponse.setStatus(true);       apiResponse.setMessage("Users Created Successfully ");       apiResponse.setCode("USERS_CREATED");       apiResponse.setData(responseDTOS);       return ResponseEntity.ok(responseDTOS);    }    @GetMapping ("/{id}")    public ResponseEntity<UserResponseDTO> getUser (@PathVariable Long id){        UserResponseDTO userResponseDTO = userServiceImp.getUser(id);        APIResponse<UserResponseDTO> apiResponse = new APIResponse<>();        apiResponse.setStatus(true);        apiResponse.setCode("USER_FOUND");        apiResponse.setMessage("User Retrieved successfully");        apiResponse.setData(userResponseDTO);        return ResponseEntity.ok(userResponseDTO);    }    @GetMapping ("/all")    public ResponseEntity<PagedResponse<UserResponseDTO>> getAllUsers (@RequestParam(required = false) String search,                                                                       @RequestParam (defaultValue = "10") int size,                                                                       @RequestParam (defaultValue = "0") int page,                                                                       @RequestParam (defaultValue = "DESC")SortDirection sortDirection,                                                                       @RequestParam (defaultValue = "ID")UserSortField userSortField){        PagedResponse<UserResponseDTO> response = userServiceImp.getAllUsers(search,size,page,userSortField,sortDirection);       APIResponse<PagedResponse<UserResponseDTO>> apiResponse = new APIResponse<>();       apiResponse.setStatus(true);       apiResponse.setCode("USERS_FOUND");       apiResponse.setMessage("Bulk Users have retrieved Successfully");       apiResponse.setData(response);       return ResponseEntity.ok(response);    }    @GetMapping ("/{ids}")    public ResponseEntity<List<UserResponseDTO>> getUsersById (@PathVariable List<Long>ids){        List<UserResponseDTO> responseDTOS = userServiceImp.getUsersById(ids);        APIResponse<List<UserResponseDTO>> apiResponse = new APIResponse<>();        apiResponse.setStatus(true);        apiResponse.setMessage("USERS_FOUND");        apiResponse.setMessage("Users retrieved successfully");        apiResponse.setData(responseDTOS);        return ResponseEntity.ok(responseDTOS);    }    @PutMapping ("/{id}")    public ResponseEntity<Optional<UserResponseDTO>> updateUser (@PathVariable Long id,@RequestBody UserRequestDTO dto){        Optional<UserResponseDTO> responseDTO = userServiceImp.updateUser(id,dto);       APIResponse<Optional<UserResponseDTO>> apiResponse = new APIResponse<>();       apiResponse.setStatus(true);       apiResponse.setCode("USER_UPDATED");       apiResponse.setMessage("Users updated Successfully");       apiResponse.setData(responseDTO);       return ResponseEntity.ok(responseDTO);    }    @DeleteMapping ("/{id}")    public ResponseEntity<Void> deleteUser (@PathVariable Long id,@RequestParam boolean confirm){        userServiceImp.deleteUser(id,confirm);       APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setStatus(true);        apiResponse.setMessage("USER_DELETED");        apiResponse.setMessage("User Deleted successfully");        apiResponse.setData(null);        return ResponseEntity.noContent().build();    }    @DeleteMapping ("/all")    public ResponseEntity<Void> deleteAll (@RequestParam boolean confirm){        userServiceImp.deleteAll(confirm);        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setStatus(true);        apiResponse.setMessage("USERS_DELETED");        apiResponse.setMessage("All Users Deleted successfully");        apiResponse.setData(null);        return ResponseEntity.noContent().build();    }    @DeleteMapping("/{ids}")    public ResponseEntity<List<Void>> deleteByIds (@PathVariable List<Long>ids, @RequestParam boolean confirm){        userServiceImp.deleteById(ids,confirm);        APIResponse<List<Void>> apiResponse = new APIResponse<>();        apiResponse.setStatus(true);        apiResponse.setMessage("USERS_DELETED");        apiResponse.setMessage("Users Deleted successfully");        apiResponse.setData(null);        return ResponseEntity.noContent().build();    }}